{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Hydrochlorothiazide, the saturated analogue of the query with the same benzothiadiazine sulfonamide core, has absolute oral bioavailability of 65–75% in humans, strongly supporting high F for the closely related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Absolute oral bioavailability of hydrochlorothiazide was measured as 60.2% in humans after oral dosing, providing a quantitative high-bioavailability anchor for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Metolazone, a thiazide-like sulfonamide diuretic, is approximately 100% bioavailable in humans, supporting high oral bioavailability across the thiazide-related diuretic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Azosemide, a less similar sulfonamide diuretic, has low oral bioavailability of 10–19% in humans due to first-pass metabolism; this contradictory example is outweighed by the much closer hydrochlorothiazide evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is chlorothiazide, the unsaturated analogue of hydrochlorothiazide. The closest and most transferable evidence (HCTZ, Morgan similarity 0.511) shows absolute oral bioavailability of 60–75% in humans, strongly supporting F ≥20%. Additional thiazide-like diuretics also show high bioavailability. A less similar sulfonamide diuretic with low F does not override the close HCTZ anchor. Physicochemical absorption concerns are outweighed by experimental class evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for chlorothiazide itself was provided.",
    "First-pass metabolism and transporter effects for the query are not directly characterized.",
    "The closest analogue is saturated (HCTZ) while the query is unsaturated, which may modestly alter absorption and bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

